<!--vbase-->
<template>
  <q-btn flat class="key-card" @click="showKeyboardShortcuts = true">
    <q-icon
      name="keyboard"
      width="24"
      class="keyboard-icon cursor-pointer"
      @click="showKeyboardShortcuts = true"
    >
      <q-tooltip>{{ $t('keyboard_shortcut') }}</q-tooltip>
    </q-icon>
  </q-btn>

  <!-- Keyboard Shortcuts -->
  <q-dialog
    v-model="showKeyboardShortcuts"
    @keydown.esc="showKeyboardShortcuts = false"
  >
    <q-card>
      <keyboardShortcutInfo />
      <q-card-actions align="right">
        <q-btn
          flat
          color="primary"
          :label="$t('close')"
          class="float-right"
          style="font-weight: 900"
          @click="showKeyboardShortcuts = false"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Keyboard Shortcuts -->
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import keyboardShortcutInfo from './ShortcutInfo.vue';
import keyboardUtil from 'src/utils/keyboard';

export default defineComponent({
  el: '#app',
  mixins: [keyboardUtil],
  props: {},
  components: {
    keyboardShortcutInfo,
  },
  mounted: function () {
    window.addEventListener('keydown', this.keyboardKeyDownEvent);
  },
  unmounted: function () {
    window.removeEventListener('keydown', this.keyboardKeyDownEvent);
  },
  methods: {
    keyboardKeyDownEvent(event: any) {
      const combKey = this.isCombinationKey(event);
      // h key
      if (event.keyCode === 75 && combKey === true) {
        event.preventDefault();
        this.showKeyboardShortcuts = true;
      }
    },
  },
  data() {
    return {};
  },
  setup() {
    return {
      showKeyboardShortcuts: ref(false),
    };
  },
});
</script>

<style lang="css" scoped>
.key-card {
  padding: 2px 2px;
}
.keyboard-icon {
  color: #7a7a7a;
  font-size: 30px;
}
</style>
